const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const pages=[['overview','◫','Overview'],['balance','⇄','Energy balance'],['electricity','ϟ','Electricity'],['petroleum','♧','Petroleum'],['coal','◇','Coal'],['biomass','♧','Biomass'],['economic','↗','Economic indicators'],['emissions','◎','Grid emissions'],['buildings','▥','Buildings & ISIC']];
const work=[['submissions','⇧','Data submissions'],['review','☷','Verification queue'],['reports','▤','Reports & exports'],['admin','⚙','Administration']];
const colors=['#3f8866','#91c47a','#cfdf9a','#edb779','#86b4bd'];
const sources=['Petroleum','Biomass','Coal','Hydro','Solar & wind'], sectors=['Transport','Industry','Households','Commercial'];
const matrix=[[150,35,10,5],[0,85,75,5],[0,35,0,0],[0,18,10,7],[0,8,5,2]];
let page='overview', view='flow',compare='2023',ascending=false, showShare=true, forecast=false;
let submissions=[{id:'SUB-024',org:'CEB',dataset:'Electricity generation',period:'2024 · Annual',value:16200,status:'Awaiting review',version:1},{id:'SUB-023',org:'CPC',dataset:'Petroleum imports',period:'2024 · Annual',value:200,status:'Revision requested',version:2},{id:'SUB-022',org:'SLSEA',dataset:'Building energy',period:'2024 · Annual',value:58,status:'Approved',version:1},{id:'SUB-021',org:'Litro Gas',dataset:'LPG sales',period:'2024 · Annual',value:14,status:'Approved',version:1}];
let audit=[{time:'Sample event',actor:'Verifier · SLSEA',action:'Approved SUB-022',version:'v1'}];
let coefficient=0.52;
const factor=()=>({'PJ':1,ktoe:23.88458966,GWh:277.7777778,TJ:1000}[$('#unit').value]);
const yf=y=>({2020:.85,2021:.9,2022:.87,2023:.94,2024:1}[y]||1);
const year=()=>$('#year').value, unit=()=>$('#unit').value;
const total=(y=year())=>matrix.reduce((sum,row,i)=>sum+row.reduce((s,v,j)=>s+(($('#source').value==='All sources'||$('#source').value===sources[i])&&($('#sector').value==='All sectors'||$('#sector').value===sectors[j])?v:0),0),0)*yf(y);
const fmt=(v,d=1)=>Number(v).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const energy=v=>fmt(v*factor());
const bySource=()=>sources.map((name,i)=>({name,value:matrix[i].reduce((s,v,j)=>s+(($('#sector').value==='All sectors'||$('#sector').value===sectors[j])?v:0),0)*yf(year())})).filter(r=>$('#source').value==='All sources'||r.name===$('#source').value);
const bySector=()=>sectors.map((name,j)=>({name,value:matrix.reduce((s,row,i)=>s+(($('#source').value==='All sources'||$('#source').value===sources[i])?row[j]:0),0)*yf(year())})).filter(r=>$('#sector').value==='All sectors'||r.name===$('#sector').value);
const spark=()=>'<svg class="sparkline" viewBox="0 0 70 30"><path d="M0 26L8 22L15 24L25 13L34 17L42 9L51 14L60 5L70 2" fill="none" stroke="#74a484" stroke-width="1.5"/></svg>';
const metric=(label,value,u,note='Illustrative annual value')=>`<div class="metric"><div class="metric-label">${label}<button data-method="${label}" aria-label="Methodology for ${label}">ⓘ</button></div><div class="metric-number">${value}<small>${u}</small></div><div class="metric-note">${note}</div>${spark()}</div>`;
const title=(t,sub,right='')=>`<div class="card-title"><div><h2>${t}</h2><p>${sub}</p></div>${right}</div>`;
const foot=()=>`<div class="chart-foot"><span>Synthetic demonstration dataset · ${year()} · ${unit()}</span><button class="link-button" data-method="Energy methodology">View methodology ↗</button></div>`;
const legend=()=>`<div class="legend">${sources.map((s,i)=>`<span><i class="dot" style="--c:${colors[i]}"></i>${s}</span>`).join('')}</div>`;
function flow(){
 const selected=bySource(), dest=bySector(); const sum=total();if(!sum)return '<div class="empty">No energy flows for the selected combination.</div>';
 let sy=40,ty=40;let left=[],right=[],paths=[];
 selected.forEach(s=>{let i=sources.indexOf(s.name),h=s.value/sum*205;left.push({s,i,y:sy,h});sy+=h+10});
 dest.forEach(s=>{let h=s.value/sum*205;right.push({s,y:ty,h});ty+=h+10});
 const leftOff={},rightOff={};
 left.forEach(l=>right.forEach(r=>{const j=sectors.indexOf(r.s.name),v=matrix[l.i][j]*yf(year());if(!v)return;const h=v/sum*205,a=l.y+(leftOff[l.i]||0),b=r.y+(rightOff[j]||0);leftOff[l.i]=(leftOff[l.i]||0)+h;rightOff[j]=(rightOff[j]||0)+h;paths.push(`<path d="M126 ${a+h/2} C265 ${a+h/2} 310 ${b+h/2} 460 ${b+h/2}" stroke="${colors[l.i]}" stroke-opacity=".23" stroke-width="${h}" fill="none"><title>${l.s.name} → ${r.s.name}: ${energy(v)} ${unit()}</title></path>`)}));
 return `<svg viewBox="0 0 590 310" role="img" aria-label="Energy flow from primary sources to final consumption sectors"><text x="0" y="14" style="letter-spacing:1.5px;font-size:8px">PRIMARY ENERGY SOURCES</text><text x="452" y="14" style="letter-spacing:1.5px;font-size:8px">FINAL CONSUMPTION</text>${paths.join('')}${left.map(l=>`<rect x="117" y="${l.y}" width="9" height="${Math.max(l.h,1)}" rx="2" fill="${colors[l.i]}"/><text x="0" y="${l.y+l.h/2-2}">${l.s.name}</text><text class="value" x="0" y="${l.y+l.h/2+13}">${energy(l.s.value)}</text>`).join('')}${right.map(r=>`<rect x="460" y="${r.y}" width="9" height="${Math.max(r.h,1)}" rx="2" fill="#729480"/><text x="482" y="${r.y+r.h/2-2}">${r.s.name}</text><text class="value" x="482" y="${r.y+r.h/2+13}">${energy(r.s.value)}</text>`).join('')}</svg>`;
}
function mix(){const a=bySource(),sum=total();let n=0;const grad=a.map(s=>{let start=n;n+=sum?s.value/sum*100:0;return `${colors[sources.indexOf(s.name)]} ${start}% ${n}%`}).join(',');return `<div class="mix-body"><div class="donut" style="background:${sum?`conic-gradient(${grad})`:'#edf1e9'}"><div class="donut-inner"><b>${energy(sum)}</b><span>Total ${unit()}</span></div></div><div class="mix-legend">${a.map(s=>`<div class="mix-row"><span><i class="dot" style="--c:${colors[sources.indexOf(s.name)]}"></i>${s.name}</span><b>${sum?fmt(s.value/sum*100,0):0}%</b></div>`).join('')}</div></div>`}
function bars(rows=bySector()){const max=Math.max(...rows.map(s=>s.value),1);return `<div class="sector-bars">${rows.map((s,i)=>`<div><div class="bar-label"><span>${s.name}</span><b>${energy(s.value)} ${unit()}</b></div><div class="bar-track"><div class="bar-fill" style="width:${s.value/max*100}%;--c:${colors[i%5]}"></div></div></div>`).join('')}</div>`}
function trend(){const values=[total('2020'),total('2021'),total('2022'),total('2023'),total('2024')],max=Math.max(...values,1)*1.2;const point=(v,i)=>`${48+i*112},${153-v/max*120}`;let path=values.map(point).join(' ');return `<svg viewBox="0 0 540 188" role="img" aria-label="Illustrative energy trend 2020 to 2024">${[0,1,2,3].map(i=>`<line x1="45" x2="510" y1="${33+i*40}" y2="${33+i*40}" stroke="#edf1e9"/><text x="0" y="${37+i*40}">${fmt(max*(1-i/3)*factor(),0)}</text>`).join('')}<path d="M48 153 L${path} L496 153 Z" fill="#eef5ea"/><polyline points="${path}" fill="none" stroke="#69966d" stroke-width="2.5"/>${values.map((v,i)=>`<circle cx="${48+i*112}" cy="${153-v/max*120}" r="3.5" fill="white" stroke="#69966d" stroke-width="2"><title>${2020+i}: ${energy(v)} ${unit()}</title></circle><text x="${35+i*112}" y="178">${2020+i}</text>`).join('')}${forecast?`<path d="M496 ${153-values[4]/max*120} l28 -7" stroke="#da9b56" stroke-width="2" stroke-dasharray="4 4"/><text x="360" y="17">2025 projection: ${energy(values[4]+(values[4]-values[0])/4)} ${unit()}</text>`:''}</svg>`}
function dataTable(rows=bySource(),label='Energy source'){let a=[...rows].sort((x,y)=>ascending?x.value-y.value:y.value-x.value);return `<div class="table-toggle"><label><input id="share-toggle" type="checkbox" ${showShare?'checked':''}> Show share column</label><button class="link-button" id="sort">Sort by consumption ${ascending?'↑':'↓'}</button></div><div class="table-wrap"><table><thead><tr><th>${label}</th><th>${year()} (${unit()})</th><th>${compare} (${unit()})</th>${showShare?'<th>Share</th>':''}<th>Data status</th></tr></thead><tbody>${a.map(r=>`<tr><td>${r.name}</td><td>${energy(r.value)}</td><td>${energy(r.value/yf(year())*yf(compare))}</td>${showShare?`<td>${total()?fmt(r.value/total()*100):0}%</td>`:''}<td><span class="status">Illustrative</span></td></tr>`).join('')}</tbody></table></div>`}
function overview(){let sum=total(),previous=total('2023'),renew=bySource().filter(s=>['Biomass','Hydro','Solar & wind'].includes(s.name)).reduce((s,r)=>s+r.value,0);return `<div class="metrics">${metric('Final energy consumption',energy(sum),unit(),`<span>↗ ${previous?fmt((sum/previous-1)*100):'0'}%</span> vs 2023 · demo`)}${metric('Renewable energy share',sum?fmt(renew/sum*100):'0','%', 'Share of selected final consumption')}${metric('Grid emission factor',fmt(coefficient*yf(year()),3),'tCO₂/MWh','Demo coefficient · methodology pending')}${metric('Reporting organisations','24','entities','Synthetic reporting population')}</div><div class="grid"><section class="card sankey">${title('A nation’s energy, connected',`Source-to-sector flow · ${year()} · ${unit()}`,`<div class="segmented"><button id="flow-view" class="${view==='flow'?'selected':''}">Flow</button><button id="table-view" class="${view==='table'?'selected':''}">Table</button></div>`)}${view==='flow'?flow():dataTable()}${view==='flow'?legend():''}${foot()}</section><section class="card">${title('What powers Sri Lanka?',`Final energy mix · ${year()}`,`<span class="tag">${unit()}</span>`)}${mix()}<div class="insight">↗ <b>Explore the transition.</b> Filter a source or sector to see how its contribution changes.</div>${foot()}</section></div><div class="grid"><section class="card trend">${title('Energy use through the years','Annual final consumption · illustrative series',`<button class="link-button" id="forecast">${forecast?'Hide projection':'Show projection ↗'}</button>`)}${trend()}${foot()}</section><section class="card">${title('Where energy is used',`Final consumption by sector · ${year()}`,`<span class="tag">${unit()}</span>`)}${bars()}${foot()}</section></div>`}
const moduleConfig={electricity:{title:'Electricity',sub:'Explore generation, capacity, demand and the national load profile.',items:['Major hydro','CEB thermal (coal)','CEB thermal (oil)','SPP solar','SPP wind','SPP biomass'],values:[6000,5800,2100,1500,600,200],u:'GWh',names:['Generation summary','Installed capacity','Load profile','Sales & consumer accounts']},petroleum:{title:'Petroleum',sub:'Follow imports, refinery outputs, product sales and fuel prices.',items:['Diesel','Petrol','Furnace oil','Kerosene','LPG'],values:[94,52,24,16,14],u:'PJ',names:['Imports','Refinery products','Product sales','Prices & financial data']},coal:{title:'Coal',sub:'Track coal imports and consumption across electricity and industry.',items:['Power generation','Industrial consumption'],values:[28,7],u:'PJ',names:['Imports','Consumption']},biomass:{title:'Biomass',sub:'Understand fuelwood, charcoal and biogas use across sectors.',items:['Household fuelwood','Industrial fuelwood','Charcoal','Biogas'],values:[75,70,15,5],u:'PJ',names:['Fuelwood consumption','Charcoal & biogas']},economic:{title:'Economic indicators',sub:'Connect energy use with economic activity and social indicators.',items:['Industry','Transport','Residential','Services'],values:[181,150,100,19],u:'PJ',names:['Key energy indicators','Energy & GDP','Petroleum trade balance','Population & GDP']}};
let moduleTab=0,selectedCategories=new Set();
function modulePage(){const c=moduleConfig[page];let mult=moduleTab===1?.4:moduleTab===2?.75:1;let rows=c.items.map((name,i)=>({name,value:c.values[i]*yf(year())*mult})).filter(r=>!selectedCategories.size||selectedCategories.has(r.name));let max=Math.max(...rows.map(r=>r.value),1);return `<div class="notice">Concept view · ${c.names[moduleTab]}. Values are synthetic. ${c.u==='GWh'?'Generation uses GWh; capacity uses illustrative MW. Load and sales views are sample series.':'Energy totals convert with the selected unit.'}</div><div class="actions full">${c.names.map((n,i)=>`<button data-tab="${i}" class="${moduleTab===i?'primary':''}">${n}</button>`).join('')}</div><div class="grid"><section class="card">${title(c.names[moduleTab],`${year()} · ${page==='electricity'?(moduleTab===1?'MW':'GWh'):unit()}`)}<div class="legend">${c.items.map(n=>`<label><input type="checkbox" data-cat="${n}" ${selectedCategories.has(n)||!selectedCategories.size?'checked':''}>${n}</label>`).join('')}</div><div class="sector-bars">${rows.map((r,i)=>`<div><div class="bar-label"><span>${r.name}</span><b>${fmt(r.value*(page==='electricity'?1:factor()))}</b></div><div class="bar-track"><div class="bar-fill" style="width:${r.value/max*100}%;--c:${colors[i%5]}"></div></div></div>`).join('')}</div>${foot()}</section><section class="card">${title('Historical comparison','Compare the selected reporting period with another year')}<div class="period-compare">Compare with ${compareSelect()}</div><div class="table-wrap"><table><thead><tr><th>Category</th><th>${year()}</th><th>${compare}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.name}</td><td>${fmt(r.value*(page==='electricity'?1:factor()))}</td><td>${fmt(r.value/yf(year())*yf(compare)*(page==='electricity'?1:factor()))}</td></tr>`).join('')}</tbody></table></div>${foot()}</section></div>`}
function compareSelect(){return `<select id="compare" aria-label="Comparison year">${[2020,2021,2022,2023,2024].map(y=>`<option ${String(y)===compare?'selected':''}>${y}</option>`).join('')}</select>`}
function balance(){return `${overview()}<section class="card full">${title('Annual Energy Balance','Reconciled demonstration flow · source and use totals match')}<div class="period-compare">Comparison year ${compareSelect()}</div>${dataTable()}<div class="insight">This simplified final-consumption flow totals ${energy(total())} ${unit()}. The production balance must include original units and TJ tables, imports, exports, stock changes, transformations and losses from SLSEA-approved workbooks.</div></section>`}
let isic='All building types';
const buildingRows=[['C · Manufacturing','ISIC 10–33',12,82],['G · Wholesale & retail','ISIC 45–47',8,118],['I · Accommodation','ISIC 55',9,155],['Q · Health services','ISIC 86',7,142],['P · Education','ISIC 85',5,64]];
function buildings(){let rows=buildingRows.filter(r=>isic==='All building types'||r[0]===isic);return `<div class="notice">Building energy analysis supports NDC 2.2–2.4 and ISIC-based reporting. Codes below are indicative; the official classification mapping and benchmarks must be confirmed with SLSEA.</div><div class="period-compare"><label for="isic">Building type</label><select id="isic"><option>All building types</option>${buildingRows.map(r=>`<option ${isic===r[0]?'selected':''}>${r[0]}</option>`).join('')}</select></div><div class="metrics">${metric('Total building energy',energy(rows.reduce((s,r)=>s+r[2],0)*yf(year())),unit())}${metric('Electricity EUI',fmt(rows.reduce((s,r)=>s+r[3],0)/rows.length,0),'kWh/m²/yr','Unweighted mean · demonstration')}${metric('Buildings represented',fmt(rows.length*48,0),'buildings','Synthetic building sample')}${metric('Reporting coverage','86','%','Illustrative reporting coverage')}</div><div class="grid"><section class="card">${title('Annual consumption by ISIC building type',`Disaggregated fuel mix · ${year()} · ${unit()}`)}${rows.map(r=>`<div class="bar-label"><span>${r[0]}</span><b>${energy(r[2]*yf(year()))}</b></div><div style="display:flex;height:24px;max-width:${r[2]/12*100}%;margin:8px 0 22px;border-radius:4px;overflow:hidden">${[.5,.2,.15,.1,.05].map((v,i)=>`<div style="width:${v*100}%;background:${colors[i]}"><title>${sources[i]}</title></div>`).join('')}</div>`).join('')}${legend()}${foot()}</section><section class="card">${title('Energy use intensity','Electricity per gross floor area · kWh/m²/year')}<div class="sector-bars">${rows.map(r=>`<div><div class="bar-label"><span>${r[0]}</span><b>${r[3]}</b></div><div class="bar-track"><div class="bar-fill" style="width:${r[3]/160*100}%;--c:#77a184"></div></div></div>`).join('')}</div><div class="insight">EUI = annual electricity consumption (kWh) ÷ gross floor area (m²). Compare buildings with similar use, climate and occupancy.</div></section></div><section class="card">${title('Building energy register','Illustrative sector aggregates')}<div class="table-wrap"><table><thead><tr><th>Building type</th><th>ISIC code</th><th>Consumption (${unit()})</th><th>EUI (kWh/m²/yr)</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${energy(r[2]*yf(year()))}</td><td>${r[3]}</td></tr>`).join('')}</tbody></table></div></section>`}
function emissions(){return `<div class="notice">Demonstration factors only. Official operating margin, build margin, combined margin and average emission factors require SLSEA-approved methods, assumptions and source inputs.</div><div class="metrics">${metric('Operating margin',fmt(.71*yf(year()),3),'tCO₂/MWh')}${metric('Build margin',fmt(.33*yf(year()),3),'tCO₂/MWh')}${metric('Combined margin',fmt(coefficient*yf(year()),3),'tCO₂/MWh','Demo: 50% OM + 50% BM')}${metric('Average emission factor',fmt(.48*yf(year()),3),'tCO₂/MWh')}</div><section class="card full">${title('Grid emissions: historical comparison','Synthetic annual factors · tCO₂/MWh')}<div class="period-compare">Compare ${year()} with ${compareSelect()}</div><table><thead><tr><th>Indicator</th><th>${year()}</th><th>${compare}</th></tr></thead><tbody>${[['Operating margin',.71],['Build margin',.33],['Combined margin',coefficient],['Average emission factor',.48]].map(r=>`<tr><td>${r[0]}</td><td>${fmt(r[1]*yf(year()),3)}</td><td>${fmt(r[1]*yf(compare),3)}</td></tr>`).join('')}</tbody></table>${foot()}</section><section class="card">${title('Calculation transparency','Illustrative calculation only')}<p>Combined margin = 0.5 × operating margin + 0.5 × build margin.</p><p class="subtle">Example: 0.5 × 0.710 + 0.5 × 0.330 = 0.520 tCO₂/MWh. The production system will use the approved methodology and retain parameter versions and source references.</p></section>`}
function badge(s){return `<span class="status ${s==='Awaiting review'||s==='Draft'?'pending':s==='Revision requested'?'revision':''}">${s}</span>`}
function submissionTable(review=false){let rows=submissions.filter(s=>review?s.status==='Awaiting review':$('#role').value==='Data Provider'?s.org==='CEB':true);return `<div class="table-wrap"><table><thead><tr><th>Organisation / reference</th><th>Dataset</th><th>Period</th><th>Status</th><th>${review?'Decision':'Version'}</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${s.org}<br><small>${s.id}</small></td><td>${s.dataset}</td><td>${s.period}</td><td>${badge(s.status)}</td><td>${review?`<button class="link-button" data-review="${s.id}">Review →</button>`:`v${s.version}`}</td></tr>`).join('')||'<tr><td colspan="5">No submissions to show.</td></tr>'}</tbody></table></div>`}
function submissionsPage(){const can=['Data Provider','Administrator'].includes($('#role').value);return `<div class="notice">Role preview: <strong>${$('#role').value}</strong>. Switch to Data Provider or Administrator to try data entry. This is a simulation; no authentication or server storage is connected. Demo records last for this browser tab.</div><section class="card full">${title('Organisation submissions','CEB is the sample provider organisation. Each action creates a demo audit event.',can?'<button class="primary" id="new-submission">+ New submission</button>':'')}${submissionTable()}</section><section class="card">${title('Structured data capture','Online form → validation → review → approval')}<div class="actions"><button id="template">↓ Download demo CSV template</button><button data-method="Excel imports">Excel import concept ⓘ</button></div><div class="insight">The production platform requires approved Excel templates, bulk validation, draft versioning, organisation restrictions and daily, monthly, quarterly, annual and ad hoc schedules.</div></section>`}
function reviewPage(){if(!['Verifier','Administrator'].includes($('#role').value))return '<div class="empty">Verification is available in the Verifier and Administrator role previews. Use the role selector above to explore this journey.</div>';return `<section class="card full">${title('Verification queue','Review data quality and request corrections before approval')}${submissionTable(true)}</section>${auditTable()}`}
function auditTable(){return `<section class="card full">${title('Activity & audit trail','Local demo events · production retention requirement: at least five years')}<div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Version</th></tr></thead><tbody>${audit.map(e=>`<tr><td>${e.time}</td><td>${e.actor}</td><td>${e.action}</td><td>${e.version}</td></tr>`).join('')}</tbody></table></div></section>`}
function reports(){return `<div class="grid"><section class="card">${title('Build an energy report','Choose content, then preview a printable report.')}<div class="report-list">${[['summary','National overview & key indicators'],['flow','Energy flow diagram'],['mix','Energy mix'],['table','Source comparison table']].map(([v,n])=>`<label><input type="checkbox" name="report-section" value="${v}" checked>${n}</label>`).join('')}</div><div class="actions" style="margin-top:24px"><button class="primary" id="report-preview">Preview report →</button><button id="csv-report">↓ Export CSV</button></div></section><section class="card">${title('Export details','Metadata accompanies the CSV download')}<p>Period: ${year()} · Unit: ${unit()}<br>Source: Synthetic demonstration data<br>Geography: Sri Lanka (national)<br>Verification status: Illustrative<br>Source filter: ${$('#source').value}<br>Sector filter: ${$('#sector').value}</p><div class="insight">PDF uses the browser’s Print / Save as PDF function. Native XLSX, PNG and JPEG exports are part of the production specification.</div></section></div>`}
function admin(){if($('#role').value!=='Administrator')return '<div class="empty">Choose Administrator in the role preview to explore configuration and audit screens.</div>';return `<div class="notice">Administration concept · These controls change demo configuration only. MFA, access enforcement, encryption, backup operations and monitoring require production services.</div><div class="admin-grid full"><section class="card">${title('Calculation & validation rules','Illustrative parameter registry · changes are logged')}<form id="config"><div class="config-row"><label for="emission-factor">Demo combined margin (tCO₂/MWh)</label><input id="emission-factor" type="number" step="0.001" min="0" max="2" value="${coefficient}" required></div><div class="config-row"><span>Energy conversion</span><strong>1 PJ = 1,000 TJ</strong></div><div class="config-row"><span>Energy conversion</span><strong>1 ktoe = 0.041868 PJ</strong></div><div class="config-row"><span>Historical deviation threshold</span><strong>±20% (demo)</strong></div><button class="primary" style="margin-top:18px">Save demo parameter</button></form></section><section class="card">${title('Security & operations','Production controls required by the tender')}${[['Authentication','MFA for administrators'],['Permissions','Organisation-scoped RBAC'],['Backup & recovery','Scheduled + restore testing'],['Data retention','30+ years online; older archives'],['Audit retention','At least 5 years'],['Integrations','Benchmarking / dispatch: future APIs']].map(([a,b])=>`<div class="config-row"><span>${a}</span><strong>${b}</strong></div>`).join('')}</section></div>${auditTable()}`}
function render(){let c=moduleConfig[page],name=[...pages,...work].find(p=>p[0]===page)?.[2]||'Overview';$('#crumb').textContent=name;$('#page-title').textContent=page==='overview'?'The energy behind our nation.':c?c.title:name;$('#page-subtitle').textContent=c?c.sub:({overview:'Explore the supply, transformation and use of energy across Sri Lanka.',balance:'Follow energy from its source to the sectors that depend on it.',buildings:'Measure building performance and support energy efficiency reporting.',emissions:'Trace the factors that connect energy use and emissions.',submissions:'A structured workspace for accurate and auditable energy data.',review:'Validate submissions and keep every decision traceable.',reports:'Turn energy data into useful, shareable evidence.',admin:'Manage calculation rules, metadata and governance.'}[page]);$('#content').innerHTML=page==='overview'?overview():page==='balance'?balance():c?modulePage():page==='buildings'?buildings():page==='emissions'?emissions():page==='submissions'?submissionsPage():page==='review'?reviewPage():page==='reports'?reports():admin();$$('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));bind();}
function modal(t,html){$('#modal-title').textContent=t;$('#modal-content').innerHTML=html;$('#modal').showModal()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function log(action,version=1){audit.unshift({time:new Date().toLocaleString('en-GB',{timeZone:'Asia/Colombo'})+' LK',actor:$('#role').value+' · SLSEA demo',action:escapeHTML(action),version:'v'+version})}
function download(name,content,type='text/csv;charset=utf-8'){let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportCSV(){let rows=bySource();if(page==='buildings')rows=buildingRows.filter(r=>isic==='All building types'||r[0]===isic).map(r=>({name:r[0],value:r[2]*yf(year())}));if(moduleConfig[page]){let c=moduleConfig[page];rows=c.items.map((n,i)=>({name:n,value:c.values[i]*yf(year())}));}const isElec=page==='electricity';let lines=[['Title',page+' · demonstration export'],['Source','Synthetic data; not SLSEA official statistics'],['Period',year()],['Unit',isElec?'GWh':unit()],['Generated',new Date().toISOString()],['Source filter',$('#source').value],['Sector filter',$('#sector').value],['Status','Illustrative'],['Category','Value'],...rows.map(r=>[r.name,fmt(r.value*(isElec?1:factor()))])];download('energy-'+page+'-'+year()+'.csv',lines.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'));toast('CSV downloaded with demonstration metadata')}
function newSubmission(){modal('New energy submission',`<form id="submission-form"><div class="form-grid"><label>Organisation<input value="CEB" disabled></label><label>Dataset<select id="dataset"><option>Electricity generation</option><option>Building energy</option><option>Petroleum imports</option></select></label><label>Reporting year<select id="submit-year">${[2024,2023,2022].map(y=>`<option>${y}</option>`).join('')}</select></label><label>Frequency<select id="frequency"><option>Annual</option><option>Quarterly</option><option>Monthly</option><option>Daily</option><option>Ad hoc</option></select></label><label class="wide">Energy value (GWh)<input type="number" id="submit-value" min="0" step="0.01" required placeholder="Enter a non-negative value"></label></div><p id="validation" class="field-error" role="alert"></p><div class="actions"><button type="button" id="save-draft">Save draft</button><button class="primary">Validate & submit</button></div></form>`);const save=status=>{let field=$('#submit-value');if(!field.reportValidity())return;let val=+field.value;if(status!=='Draft'&&Math.abs(val/16200-1)>.2){$('#validation').textContent='Historical plausibility check: value differs by more than 20% from the demo baseline (16,200 GWh). Correct the value or save a draft for clarification.';return}let s={id:'SUB-'+String(25+submissions.length-4).padStart(3,'0'),org:'CEB',dataset:$('#dataset').value,period:$('#submit-year').value+' · '+$('#frequency').value,value:val,status,version:1};submissions.unshift(s);log(status+' '+s.id);$('#modal').close();render();toast(status==='Draft'?'Draft saved in this browser tab':'Submission routed to the demo verification queue')};$('#submission-form').onsubmit=e=>{e.preventDefault();save('Awaiting review')};$('#save-draft').onclick=()=>save('Draft')}
function reviewSubmission(id){let s=submissions.find(s=>s.id===id);modal('Review '+id,`<p><b>${s.org} · ${s.dataset}</b><br>${s.period} · v${s.version}<br>Submitted value: ${fmt(s.value)} GWh</p><div class="notice">Required fields complete · Non-negative value · Demo quality checks passed</div><label>Review comment<textarea id="review-comment" rows="3" style="display:block;width:100%;margin:10px 0 18px;padding:12px;border:1px solid #dce5d7;border-radius:5px" placeholder="Explain a correction or rejection"></textarea></label><div id="review-error" class="field-error" role="alert"></div><div class="actions"><button class="primary" data-decision="Approved">Approve</button><button data-decision="Revision requested">Request revision</button><button data-decision="Rejected">Reject</button></div>`);$$('[data-decision]').forEach(b=>b.onclick=()=>{let status=b.dataset.decision,comment=$('#review-comment').value.trim();if(status!=='Approved'&&!comment){$('#review-error').textContent='Add a comment explaining the requested correction or rejection.';return}s.status=status;log(status+' '+s.id+(comment?' · '+comment:''),s.version);$('#modal').close();render();toast('Review decision recorded in demo audit trail')})}
function bind(){ $$('[data-method]').forEach(b=>b.onclick=()=>modal(b.dataset.method,`<p>All figures are synthetic, created to demonstrate the tender’s required user experience. No official Energy Balance dataset was supplied.</p><p>The example flow uses a source-by-sector matrix. Totals aggregate the selected cells. Historical values use fixed annual multipliers for demonstration. Renewable share includes biomass, hydro, solar and wind in the selected final-consumption sample.</p><p>Conversions: 1 PJ = 1,000 TJ = 277.777778 GWh; 1 ktoe = 0.041868 PJ. These are energy conversions only; monetary and mass/volume conversions require appropriate approved rates or densities.</p><p>Projection: linear slope between the first and last illustrative annual observations, extended one year. This is a demonstration, not a validated forecast.</p><p>Production calculations, emissions methodologies, parameter versions and source citations must be approved by SLSEA. Reference: ToR §2.3 and Annex 1 §§3, 6.</p>`));
 $('#flow-view')?.addEventListener('click',()=>{view='flow';render()});$('#table-view')?.addEventListener('click',()=>{view='table';render()});$('#forecast')?.addEventListener('click',()=>{forecast=!forecast;render()});$('#share-toggle')?.addEventListener('change',e=>{showShare=e.target.checked;render()});$('#sort')?.addEventListener('click',()=>{ascending=!ascending;render()});$('#compare')?.addEventListener('change',e=>{compare=e.target.value;render()});$('#isic')?.addEventListener('change',e=>{isic=e.target.value;render()});$$('[data-tab]').forEach(b=>b.onclick=()=>{moduleTab=+b.dataset.tab;render()});$$('[data-cat]').forEach(b=>b.onchange=()=>{if(!selectedCategories.size)selectedCategories=new Set(moduleConfig[page].items);b.checked?selectedCategories.add(b.dataset.cat):selectedCategories.delete(b.dataset.cat);if(!selectedCategories.size)selectedCategories.add('__none');render()});$('#new-submission')?.addEventListener('click',newSubmission);$$('[data-review]').forEach(b=>b.onclick=()=>reviewSubmission(b.dataset.review));$('#template')?.addEventListener('click',()=>download('demo-energy-template.csv','organisation,dataset,year,frequency,value_gwh\r\nCEB,Electricity generation,2024,Annual,16200\r\n'));$('#csv-report')?.addEventListener('click',exportCSV);$('#config')?.addEventListener('submit',e=>{e.preventDefault();coefficient=+$('#emission-factor').value;log('Updated demo combined margin to '+coefficient);render();toast('Demo parameter saved; audit event recorded')});$('#report-preview')?.addEventListener('click',()=>{let chosen=$$('input[name="report-section"]:checked').map(n=>n.value);if(!chosen.length){toast('Select at least one report section');return}modal('Energy report · '+year(),`<p>Synthetic demonstration data · ${unit()} · Sri Lanka<br>Generated ${new Date().toLocaleDateString('en-GB',{timeZone:'Asia/Colombo'})}</p>${chosen.includes('summary')?`<h3>Final consumption: ${energy(total())} ${unit()}</h3>`:''}${chosen.includes('flow')?flow():''}${chosen.includes('mix')?mix():''}${chosen.includes('table')?dataTable():''}<p>Source: synthetic demonstration data. Not an official SLSEA publication.</p><button id="print-report" class="primary">Print / Save as PDF</button>`);$('#print-report').onclick=()=>{let w=window.open('','_blank');if(!w){toast('Allow pop-ups to open the print preview');return}w.document.write('<!doctype html><html><head><title>Energy report · Demonstration</title><style>body{font:14px Arial;color:#244535;padding:32px}svg{width:100%;max-height:360px}svg text{font:10px Arial}table{width:100%;border-collapse:collapse}td,th{padding:8px;text-align:left;border-bottom:1px solid #ddd}.table-toggle,button{display:none}.mix-row{padding:5px}h3{margin-top:25px}</style></head><body>'+$('#modal-content').innerHTML+'</body></html>');w.document.close();w.print()}})}
const navPaths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',balance:'M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4',electricity:'m13 2-9 12h7l-1 8 10-13h-7z',petroleum:'M12 3C9 8 5 12 5 15a7 7 0 0 0 14 0c0-3-4-7-7-12z M9 16c0 2 1 3 3 3',coal:'m12 3 9 7-4 11H7L3 10z M3 10h18M7 21l2-11 3-7 3 7 2 11',biomass:'M20 3C9 3 4 7 4 13a7 7 0 0 0 7 7c6 0 9-7 9-17z M3 22 15 10 M9 16v-5m0 5h5',economic:'M4 3v17h17 M7 14l4-5 4 3 5-7',emissions:'M12 3a9 9 0 1 0 9 9 M12 7a5 5 0 1 0 5 5 M12 12l8-8 M16 4h4v4',buildings:'M4 21V7h9v14 M13 12h7v9 M7 10h3m-3 4h3m-3 4h3m6-3h1m-1 3h1',submissions:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',review:'M9 5h12M9 12h12M9 19h12M3 4l1 1 2-2M3 11l1 1 2-2M3 18l1 1 2-2',reports:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8m-8 4h8',admin:'m10 3-1 3-3 1-3 3 2 3-1 3 3 3 3-1 3 2 3-2 3 1 2-3-1-3 2-3-3-3-3-1-1-3z M15 12a3 3 0 1 0-6 0 3 3 0 0 0 6 0'};
function navIcon(id){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${navPaths[id]||navPaths.overview}"/></svg>`}
$('#nav').innerHTML=pages.map(([id,icon,n])=>`<a href="#${id}"><span class="icon">${navIcon(id)}</span>${n}${id==='overview'?'<span class="arrow">›</span>':''}</a>`).join('');$('#workspace-nav').innerHTML=work.map(([id,icon,n])=>`<a href="#${id}"><span class="icon">${navIcon(id)}</span>${n}</a>`).join('');
function navigate(){let id=location.hash.slice(1);page=[...pages,...work].some(p=>p[0]===id)?id:'overview';moduleTab=0;selectedCategories.clear();$('#sidebar').classList.remove('open');render()}
window.addEventListener('hashchange',navigate);['year','source','sector','unit','role'].forEach(id=>$('#'+id).addEventListener('change',render));$('#reset').onclick=()=>{$('#year').value='2024';$('#source').value='All sources';$('#sector').value='All sectors';$('#unit').value='PJ';render()};$('#export').onclick=exportCSV;$('#close-modal').onclick=()=>$('#modal').close();$('.mobile-menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#search-form').onsubmit=e=>{e.preventDefault();let q=$('#query').value.trim().toLowerCase(),years=q.match(/20(?:20|21|22|23|24)/g);if(!q)return;let target=/emission|carbon/.test(q)?'emissions':/building|isic|intensity/.test(q)?'buildings':/electric/.test(q)?'electricity':/petroleum|diesel|petrol/.test(q)?'petroleum':/biomass|fuelwood/.test(q)?'biomass':/coal/.test(q)?'coal':/energy|balance|consumption/.test(q)?'balance':null;if(!target){$('#search-result').textContent='Try a supported query such as “Compare electricity in 2022 and 2024”, “building energy”, or “grid emissions”. This concept uses structured query patterns.';return}if(years){$('#year').value=years[years.length-1];compare=years[0]}$('#search-result').textContent=`Opened ${[...pages].find(p=>p[0]===target)[2]}${years?' for '+$('#year').value+' compared with '+compare:''}. Results use synthetic data. Structured query preview.`;if(location.hash==='#'+target)navigate();else location.hash=target};navigate();
